1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
33	// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
34	// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
35	// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
36	type idemIdentity struct {
37		submitter string
38		requestID string
39	}
40	
41	type Store struct {
42		dir string
43	
44		mu     sync.Mutex
45		jobs   []*storedJob // 严格按作业号（即提交先后）排列
46		byID   map[uint64]*storedJob
47		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
48		nextID uint64
49		closed bool
50	
51		now func() time.Time
52	
53		runningID uint64
54		waitCh    chan struct{}
55		stopCh    chan struct{}
56		stopping  atomic.Bool
57		wg        sync.WaitGroup
58	
59		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
60		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
61		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
62		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
63	
64		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
65		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
66		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
67		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
68		persistFault func(j *storedJob) error
69	}
70	
71	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
72	//
73	// 恢复语义：
74	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
75	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
76	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
77	//   - 成功状态始终与完整归档同时可见。
78	func Open(dir string, opts ...Option) (*Store, error) {
79		if err := os.MkdirAll(dir, 0o700); err != nil {
80			return nil, err
81		}
82		jobs, maxID, err := loadDir(dir)
83		if err != nil {
84			return nil, err
85		}
86		s := &Store{
87			dir:    dir,
88			jobs:   jobs,
89			byID:   make(map[uint64]*storedJob),
90			idem:   make(map[idemIdentity]uint64),
91			nextID: maxID + 1,
92			now:    wallClock{}.Now,
93			waitCh: make(chan struct{}, 1),
94			stopCh: make(chan struct{}),
95		}
96		for _, opt := range opts {
97			opt(s)
98		}
99		for _, j := range jobs {
100			s.byID[j.id] = j
101			if j.requestID != "" {
102				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
103			}
104		}
105		// 重建失败/取消作业对排队下游的阻断。
106		s.cascadeLocked()
107		s.wg.Add(1)
108		go s.worker()
109		return s, nil
110	}
111	
112	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
113	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
114	//
115	// 多次 Close（含并发调用）共同完成对同一个归档对象的一次关闭：每个调用都
116	// 等到 worker 退出、运行中作业的中断处理已经落盘后才成功返回。后发调用
117	// 不能只因为前一次调用已把关闭标记置位就提前返回——否则调用方可能据此立即
118	// 重新打开目录，而旧 worker 仍在补写运行作业的结果。归档完全关闭后的再次
119	// Close 立即成功返回；空闲归档（无运行中作业）也直接完成关闭。
120	func (s *Store) Close() error {
121		s.mu.Lock()
122		if s.closed {
123			// 关闭可能正由另一次并发 Close 进行。wg 在 Open 时 +1、worker 退出
124			// 时归零；Wait 允许被多个 goroutine 同时等待，所有调用都在同一次
125			// 关闭真正完成（worker 已退出、再无计算与补写）时才返回。
126			// 已完全关闭时计数早已归零，这里立即成功返回。
127			s.mu.Unlock()
128			s.wg.Wait()
129			return nil
130		}
131		s.closed = true
132		var running *storedJob
133		if s.runningID != 0 {
134			running = s.byID[s.runningID]
135		}
136		s.mu.Unlock()
137	
138		if s.stopping.CompareAndSwap(false, true) {
139			close(s.stopCh)
140		}
141		// 中止正在运行的计算。
142		if running != nil {
143			running.canceled.Store(true)
144		}
145		s.notify()
146		s.wg.Wait()
147		return nil
148	}
149	
150	// Submit 接受一次作业提交。
151	//
152	// 空序列返回 [ErrEmptySequence]；依赖列表结构不合法（单依赖与列表同时启用、
153	// 含零或重复作业号）返回 [ErrInvalidDependency]——这些请求本身的格式错误先于
154	// 幂等判定拒绝，即使复用已接受的请求号也不例外。
155	//
156	// 非空请求号命中同一提交人的已接受请求时，幂等判定先于“引用的上游必须存在”
157	// 校验：内容（整数序列及次序、种子、有序依赖内容）完全一致时返回原作业的
158	// 当前详情且不返回错误，即使其直接上游记录在重开归档后已缺失、原作业已因此
159	// 被改判为失败；内容不一致返回 [ErrIdempotencyConflict]（同时返回原作业视图，
160	// 仍引用缺失上游时在原因中一并指出），原记录保持原样。重复提交不创建新作业、
161	// 不补建缺失上游、不重新排队失败作业、也不改写原始参数或失败记录。
162	//
163	// 未命中已接受请求的新请求（提交人不同、请求号不同或请求号为空）引用不存在
164	// 的依赖时返回 [ErrDependencyNotFound]；上述拒绝都不产生记录，也不占用请求号。
165	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
166	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
167		s.mu.Lock()
168		defer s.mu.Unlock()
169		if s.closed || s.stopping.Load() {
170			return nil, ErrStoreClosed
171		}
172		if len(req.Values) == 0 {
173			return nil, ErrEmptySequence
174		}
175		// 先校验与上游存在性无关的列表结构（单依赖与列表互斥、零与重复作业号），
176		// 这类拒绝不依赖内存索引，对新请求与幂等重放一视同仁。
177		if err := s.validateDependencyShapeLocked(&req); err != nil {
178			return nil, err
179		}
180		deps := requestDeps(&req)
181		if req.RequestID != "" {
182			key := idemIdentity{req.Submitter, req.RequestID}
183			if origID, ok := s.idem[key]; ok {
184				orig := s.byID[origID]
185				// 幂等重放先于“引用的上游必须存在”的校验：重新打开归档后原作业
186				// 直接上游的记录可能已经缺失，原作业也因此被改判为失败并落盘。
187				// 只要本次提交的整数序列及次序、种子与有序依赖内容和已接受请求
188				// 完全一致（单依赖写法与只含同一作业号的列表等价），就返回原作业
189				// 的当前详情——不重建缺失上游、不重新排队、不补算、不改写记录。
190				if sameContent(orig, &req) {
191					return s.viewLocked(orig), nil
192				}
193				return s.viewLocked(orig),
194					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d，且本次内容与原请求不一致%s，原记录保持原样",
195						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID,
196						s.missingDependencyNoteLocked(deps))
197			}
198		}
199		// 新请求（请求号为空，或该提交人首次使用此请求号）仍要求每个直接上游
200		// 都存在；引用不存在上游的提交被拒绝，不产生记录，也不占用请求号。
201		// 此检查必须位于幂等判定之后：上面的重放/冲突分支可能引用缺失的上游。
202		if err := s.validateDependenciesExistLocked(deps); err != nil {
203			return nil, err
204		}
205	
206		now := s.now().UTC()
207		j := &storedJob{
208			id:           s.nextID,
209			submitter:    req.Submitter,
210			requestID:    req.RequestID,
211			seed:         req.Seed,
212			values:       append([]int64(nil), req.Values...),
213			dependencies: append([]uint64(nil), deps...),
214			queuedAt:     now,
215			status:       StatusQueued,
216		}
217		// 先持久化，接受之后该提交即不可丢失。
218		if err := s.persist(j); err != nil {
219			return nil, err
220		}
221		s.nextID++
222		s.jobs = append(s.jobs, j)
223		s.byID[j.id] = j
224		if req.RequestID != "" {
225			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
226		}
227		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
228		s.cascadeLocked()
229		s.notifyLocked()
230		return s.viewLocked(j), nil
231	}
232	
233	// requestDeps 规范化一次提交的直接上游作业号列表，与记录、归档共用 deps.go
234	// 中的同一换算：非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含
235	// 一个作业号的列表；两者皆无则为 nil。调用前须先经
236	// [Store.validateDependencyShapeLocked] 与（新请求路径上的）
237	// [Store.validateDependenciesExistLocked] 校验。
238	func requestDeps(req *SubmitRequest) []uint64 {
239		return normalizeDependencies(req.HasDependency, req.DependencyID, req.Dependencies)
240	}
241	
242	// validateDependencyShapeLocked 在持锁状态下校验提交依赖列表中与上游存在性
243	// 无关的结构问题：
244	//   - 单依赖方式与非空列表同时启用 → 拒绝；
245	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）。
246	//
247	// 该校验先于幂等判定执行：空整数序列、依赖号为零、重复依赖与两种写法
248	// 同时启用都属于请求本身的格式错误，即使提交人+请求号与已接受请求相同
249	// 也仍返回原有的对应拒绝。
250	func (s *Store) validateDependencyShapeLocked(req *SubmitRequest) error {
251		if req.HasDependency && len(req.Dependencies) > 0 {
252			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
253		}
254		deps := requestDeps(req)
255		seen := make(map[uint64]struct{}, len(deps))
256		for _, id := range deps {
257			if id == 0 {
258				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
259			}
260			if _, dup := seen[id]; dup {
261				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
262			}
263			seen[id] = struct{}{}
264		}
265		return nil
266	}
267	
268	// validateDependenciesExistLocked 校验规范化后的依赖列表只引用当前归档中
269	// 存在的作业。仅适用于幂等判定之后的新请求：已接受请求的重放（或内容
270	// 冲突）即使引用了重开后缺失的上游，也要返回原作业而不是被这里拒绝。
271	//
272	// 任一拒绝都不产生记录，也不占用幂等请求号。
273	func (s *Store) validateDependenciesExistLocked(deps []uint64) error {
274		for _, id := range deps {
275			if s.byID[id] == nil {
276				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
277			}
278		}
279		return nil
280	}
281	
282	// missingDependencyNoteLocked 在幂等冲突时补充说明：若本次（与原请求内容
283	// 不一致的）提交仍引用已经缺失的上游，明确指出缺失的作业号，使冲突原因
284	// 不会被误读成仅仅是上游不存在。
285	func (s *Store) missingDependencyNoteLocked(deps []uint64) string {
286		for _, id := range deps {
287			if s.byID[id] == nil {
288				return fmt.Sprintf("；本次引用的直接上游作业 %d 记录已缺失", id)
289			}
290		}
291		return ""
292	}
293	
294	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
295	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
296	func sameContent(j *storedJob, req *SubmitRequest) bool {
297		if j.seed != req.Seed {
298			return false
299		}
300		rd := requestDeps(req)
301		if len(j.dependencies) != len(rd) {
302			return false
303		}
304		for i := range j.dependencies {
305			if j.dependencies[i] != rd[i] {
306				return false
307			}
308		}
309		if len(j.values) != len(req.Values) {
310			return false
311		}
312		for i := range j.values {
313			if j.values[i] != req.Values[i] {
314				return false
315			}
316		}
317		return true
318	}
319	
320	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
321	func (s *Store) Get(id uint64) (*Job, error) {
322		s.mu.Lock()
323		defer s.mu.Unlock()
324		j := s.byID[id]
325		if j == nil {
326			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
327		}
328		return s.viewLocked(j), nil
329	}
330	
331	// Cancel 请求取消作业。
332	//
333	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
334	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
335	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
336	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
337	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
338	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
339	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
340	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
341	func (s *Store) Cancel(id uint64) (*Job, error) {
342		s.mu.Lock()
343		defer s.mu.Unlock()
344		if s.closed {
345			return nil, ErrStoreClosed
346		}
347		j := s.byID[id]
348		if j == nil {
349			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
350		}
351		switch j.status {
352		case StatusCanceled:
353			return s.viewLocked(j), nil
354		case StatusSucceeded, StatusFailed:
355			return s.viewLocked(j),
356				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
357		}
358	
359		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
360		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
361		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
362		// 不能把这次取消当作已完成。
363		now := s.now().UTC()
364		prevStatus := j.status
365		prevFinishedAt := j.finishedAt
366		prevReason := j.failureReason
367		prevBlocker := j.blockerID
368		prevEffective := j.effectiveValues
369		prevArchive := j.archive
370		j.status = StatusCanceled
371		j.failureReason = ""
372		j.blockerID = 0
373		if j.finishedAt.IsZero() {
374			j.finishedAt = now
375		}
376		j.effectiveValues = nil
377		j.archive = nil
378		if err := s.persist(j); err != nil {
379			j.status = prevStatus
380			j.finishedAt = prevFinishedAt
381			j.failureReason = prevReason
382			j.blockerID = prevBlocker
383			j.effectiveValues = prevEffective
384			j.archive = prevArchive
385			return nil, err
386		}
387	
388		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
389		j.canceled.Store(true)
390		// 依赖它的等待者一并失败，且继续向更下游传播。
391		s.cascadeLocked()
392		s.notifyLocked()
393		return s.viewLocked(j), nil
394	}
395	
396	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
397	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
398	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
399		s.mu.Lock()
400		defer s.mu.Unlock()
401		if !start.IsZero() && !end.IsZero() && start.After(end) {
402			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
403				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
404		}
405		out := make([]*Job, 0)
406		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
407			if j.submitter != submitter {
408				continue
409			}
410			if !start.IsZero() && j.queuedAt.Before(start) {
411				continue
412			}
413			if !end.IsZero() && j.queuedAt.After(end) {
414				continue
415			}
416			out = append(out, s.viewLocked(j))
417		}
418		return out, nil
419	}
420	
421	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
422	//
423	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
424	// 扫描即可让阻断沿链条传播到最下游。选择直接阻断者、确定根因与构造失败
425	// 原因统一走 blocker.go 中的规则（与重开归档同一套）：作业有多个直接上游时
426	// 按保存的依赖顺序选取最靠前的已失败/取消者，根因沿该上游已有的阻断信息
427	// 保留；作业一旦失败，其原因不再被后来发生的上游状态变化改写。
428	func (s *Store) cascadeLocked() {
429		for _, j := range s.jobs {
430			if j.status != StatusQueued || len(j.dependencies) == 0 {
431				continue
432			}
433			directID, direct, blocked := pickBlockingUpstream(j, s.byID, runtimeUpstreamBlocked)
434			if !blocked {
435				continue
436			}
437			root := blockerRoot(direct, directID)
438			s.markFailedLocked(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
439		}
440	}
441	
442	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
443	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
444	// 该作业就被跳过，不挡住后面可运行的作业。
445	func (s *Store) pickRunnableLocked() *storedJob {
446		for _, j := range s.jobs {
447			if j.status != StatusQueued {
448				continue
449			}
450			if len(j.dependencies) == 0 {
451				return j
452			}
453			ready := true
454			for _, id := range j.dependencies {
455				dep := s.byID[id]
456				if dep == nil || dep.status != StatusSucceeded {
457					ready = false
458					break
459				}
460			}
461			if ready {
462				return j
463			}
464		}
465		return nil
466	}
467	
468	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
469	func (s *Store) notifyLocked() {
470		select {
471		case s.waitCh <- struct{}{}:
472		default:
473		}
474	}
475	
476	// notify 在不持锁时唤醒 worker。
477	func (s *Store) notify() {
478		s.mu.Lock()
479		s.notifyLocked()
480		s.mu.Unlock()
481	}
482	
483	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
484	func (s *Store) persistRetry(j *storedJob, attempts int) error {
485		var err error
486		for i := 0; i < attempts; i++ {
487			if err = s.persist(j); err == nil {
488				return nil
489			}
490		}
491		return err
492	}
493	
494	// worker 是本地唯一的计算执行体。
495	func (s *Store) worker() {
496		defer s.wg.Done()
497		for {
498			s.mu.Lock()
499			if s.stopping.Load() {
500				s.mu.Unlock()
501				return
502			}
503			j := s.pickRunnableLocked()
504			if j == nil {
505				ch := s.waitCh
506				s.mu.Unlock()
507				select {
508				case <-ch:
509				case <-s.stopCh:
510				}
511				continue
512			}
513	
514			// 进入运行并原子持久化该状态。
515			j.status = StatusRunning
516			j.startedAt = s.now().UTC()
517			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
518			inputs := append([]int64(nil), j.values...)
519			for _, id := range j.dependencies {
520				if dep := s.byID[id]; dep != nil && dep.archive != nil {
521					inputs = append(inputs, dep.archive.Sum)
522				}
523			}
524			seed := j.seed
525			s.runningID = j.id
526			if err := s.persistRetry(j, 3); err != nil {
527				// 连运行状态都无法落盘：保守地失败，不进行计算。
528				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
529				s.runningID = 0
530				s.cascadeLocked()
531				s.notifyLocked()
532				s.mu.Unlock()
533				continue
534			}
535			s.mu.Unlock()
536	
537			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
538			doCompute := s.compute
539			if doCompute == nil {
540				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
541					return computeResult(in, sd, c)
542				}
543			}
544			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
545	
546			s.mu.Lock()
547			s.runningID = 0
548			switch {
549			case j.status == StatusCanceled:
550				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
551				j.archive = nil
552				j.effectiveValues = nil
553				_ = s.persistRetry(j, 3)
554				s.cascadeLocked()
555			case s.stopping.Load():
556				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
557				s.cascadeLocked()
558			case !ok:
559				s.markFailedLocked(j, reason, 0)
560				s.cascadeLocked()
561			default:
562				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
563				completed := s.now().UTC()
564				a := newArchive(j, inputs, sum, sumSq, completed)
565				j.effectiveValues = append([]int64(nil), inputs...)
566				j.status = StatusSucceeded
567				j.finishedAt = completed
568				j.failureReason = ""
569				j.blockerID = 0
570				j.archive = a
571				if err := s.persistRetry(j, 3); err != nil {
572					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
573					j.archive = nil
574					j.effectiveValues = nil
575					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
576					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
577					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
578					s.cascadeLocked()
579				}
580			}
581			s.notifyLocked()
582			s.mu.Unlock()
583		}
584	}
585	
586	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
587	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
588		j.status = StatusFailed
589		j.failureReason = reason
590		j.blockerID = blocker
591		if j.finishedAt.IsZero() {
592			j.finishedAt = s.now().UTC()
593		}
594		j.archive = nil
595		j.effectiveValues = nil
596		_ = s.persistRetry(j, 3)
597	}
598	
599	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
600	// 上游作业号只作记录，不参与任何摘要与校验值。
601	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
602		inDigest := inputsDigestHex(effective, j.seed)
603		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
604		log := buildLog(effective, j.seed, sum, sumSquares)
605		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
606		hasDependency, dependencyID := legacyDependencyFields(j.dependencies)
607		return &Archive{
608			JobID:           j.id,
609			Submitter:       j.submitter,
610			RequestID:       j.requestID,
611			IdentityRaw:     rawIdentity(j.submitter, j.requestID),
612			Seed:            j.seed,
613			Values:          append([]int64(nil), j.values...),
614			HasDependency:   hasDependency,
615			DependencyID:    dependencyID,
616			Dependencies:    append([]uint64(nil), j.dependencies...),
617			EffectiveValues: append([]int64(nil), effective...),
618			InputsDigest:    inDigest,
619			Sum:             sum,
620			SumOfSquares:    sumSquares,
621			ResultDigest:    resDigest,
622			Log:             log,
623			Checksum:        checksum,
624			CompletedAt:     completedAt,
625		}
626	}
627	
628	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
629	func (s *Store) viewLocked(j *storedJob) *Job {
630		v := &Job{
631			ID:              j.id,
632			Submitter:       j.submitter,
633			RequestID:       j.requestID,
634			Seed:            j.seed,
635			Values:          append([]int64(nil), j.values...),
636			Dependencies:    append([]uint64(nil), j.dependencies...),
637			QueuedAt:        j.queuedAt,
638			StartedAt:       j.startedAt,
639			FinishedAt:      j.finishedAt,
640			Status:          j.status,
641			FailureReason:   j.failureReason,
642			BlockerID:       j.blockerID,
643			EffectiveValues: append([]int64(nil), j.effectiveValues...),
644		}
645		v.HasDependency, v.DependencyID = legacyDependencyFields(j.dependencies)
646		if j.status == StatusQueued {
647			v.WaitReason = WaitSlot
648			// 列出尚未成功归档的直接上游，保持提交时的顺序。
649			for _, id := range j.dependencies {
650				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
651					v.PendingDependencies = append(v.PendingDependencies, id)
652				}
653			}
654			if len(v.PendingDependencies) > 0 {
655				v.WaitReason = WaitDependency
656			}
657		}
658		if j.archive != nil {
659			a := *j.archive
660			a.Values = append([]int64(nil), j.archive.Values...)
661			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
662			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
663			if j.archive.IdentityRaw != nil {
664				raw := *j.archive.IdentityRaw
665				a.IdentityRaw = &raw
666			}
667			v.Archive = &a
668		}
669		return v
670	}
671	
672	// Dir 返回归档目录路径。
673	func (s *Store) Dir() string { return s.dir }
674

