1	package numeric
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// syntheticSucceededRecord 直接在磁盘上构造一条“成功”记录：依赖列表与实际
12	// 输入由调用方给定（可以故意违反提交时的唯一性校验），归档的摘要、日志与
13	// 校验值按给定实际输入与结果经 newArchive 全套生成，因此记录在数值层面完全
14	// 自洽——用于验证恢复逻辑不能只凭结果自洽接受记录。
15	func syntheticSucceededRecord(t *testing.T, dir string, id uint64, values, eff []int64, deps []uint64, base time.Time) *storedJob {
16		t.Helper()
17		sum, sumSq, _, ok := computeResult(eff, 0, nil)
18		if !ok {
19			t.Fatalf("synthetic eff %v overflows", eff)
20		}
21		j := &storedJob{
22			id: id, submitter: "a", requestID: "j" + itoa(id),
23			values: values, dependencies: deps,
24			queuedAt:   base.Add(time.Duration(id) * time.Second),
25			startedAt:  base.Add(time.Duration(id)*time.Second + time.Millisecond),
26			finishedAt: base.Add(time.Duration(id+1) * time.Second),
27			status:     StatusSucceeded,
28		}
29		j.effectiveValues = append([]int64(nil), eff...)
30		j.archive = newArchive(j, eff, sum, sumSq, j.finishedAt)
31		writeSyntheticRecord(t, dir, j)
32		return j
33	}
34	
35	// assertDuplicateDependencyFailure 校验重复依赖记录重开后的统一形态：失败、
36	// BlockerID 为 0、无成功归档与实际输入，原因说明依赖列表重复并指出首次再次
37	// 出现的上游作业号；按作业号读取与按提交人列举一致，落盘记录同样已改写。
38	func assertDuplicateDependencyFailure(t *testing.T, s *Store, id, repeatID uint64) {
39		t.Helper()
40		g, err := s.Get(id)
41		if err != nil {
42			t.Fatal(err)
43		}
44		if g.Status != StatusFailed {
45			t.Fatalf("job %d must fail on duplicated dependency, got %s", id, g.Status)
46		}
47		if g.BlockerID != 0 {
48			t.Fatalf("duplicated dependency is the job's own error: job %d blocker=%d want 0", id, g.BlockerID)
49		}
50		if g.Archive != nil || g.EffectiveValues != nil {
51			t.Fatalf("job %d must not return archive/effective inputs: archive=%v effective=%v",
52				id, g.Archive, g.EffectiveValues)
53		}
54		if !strings.Contains(g.FailureReason, "依赖列表重复") ||
55			!strings.Contains(g.FailureReason, "作业 "+itoa(repeatID)) {
56			t.Fatalf("job %d reason=%q must state duplicated dependency list and name first repeated upstream %d",
57				id, g.FailureReason, repeatID)
58		}
59		if g.FinishedAt.IsZero() {
60			t.Fatalf("job %d failed record must keep a finished time", id)
61		}
62	
63		listed, err := s.List(g.Submitter, time.Time{}, time.Time{})
64		if err != nil {
65			t.Fatal(err)
66		}
67		found := false
68		for _, lj := range listed {
69			if lj.ID != id {
70				continue
71			}
72			found = true
73			if lj.Status != StatusFailed || lj.BlockerID != 0 ||
74				lj.Archive != nil || lj.EffectiveValues != nil ||
75				lj.FailureReason != g.FailureReason {
76				t.Fatalf("listed job %d disagrees with Get: status=%s blocker=%d reason=%q",
77					id, lj.Status, lj.BlockerID, lj.FailureReason)
78			}
79		}
80		if !found {
81			t.Fatalf("job %d missing from submitter listing", id)
82		}
83	
84		data, err := os.ReadFile(filepath.Join(s.Dir(), jobFileName(id)))
85		if err != nil {
86			t.Fatal(err)
87		}
88		text := string(data)
89		if !strings.Contains(text, `"status": "failed"`) {
90			t.Fatalf("job %d on-disk record must be failed:\n%s", id, text)
91		}
92		// blocker 为 0 时按 omitempty 不落盘；出现任何 blocker_id 都说明根因错误。
93		if strings.Contains(text, `"blocker_id"`) {
94			t.Fatalf("job %d on-disk record must have no blocker root:\n%s", id, text)
95		}
96		if strings.Contains(text, `"archive"`) {
97			t.Fatalf("job %d on-disk record must not retain archive:\n%s", id, text)
98		}
99	}
100	
101	// 规格示例：上游总和为 3，依赖列表把同一上游保存两次，实际输入 [10,3,3]，
102	// 总和 16、平方和 118，摘要、日志、校验值全部自洽——重开后仍必须判失败，
103	// 不能作为合法成功归档。被重复引用的上游保留自己的结果；等待该作业的下游
104	// 按既有规则失败，根因作业号就是这份重复记录自身。
105	func TestReopenRejectsSelfConsistentDuplicateDependency(t *testing.T) {
106		dir := t.TempDir()
107		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
108		// 作业 1：[1,2] → 总和 3。
109		up := syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
110		if up.archive.Sum != 3 {
111			t.Fatalf("upstream sum=%d want 3", up.archive.Sum)
112		}
113		// 作业 2：原始 [10]，依赖列表重复保存作业 1 两次，实际输入 [10,3,3]
114		// （总和 16、平方和 118，全套字段自洽）。
115		dup := syntheticSucceededRecord(t, dir, 2, []int64{10}, []int64{10, 3, 3}, []uint64{1, 1}, base)
116		if dup.archive.Sum != 16 || dup.archive.SumOfSquares != 118 {
117			t.Fatalf("dup result=%d,%d want 16,118", dup.archive.Sum, dup.archive.SumOfSquares)
118		}
119		// 作业 3：仍在排队等待作业 2 的下游。
120		writeSyntheticRecord(t, dir, &storedJob{
121			id: 3, submitter: "a", requestID: "child",
122			values: []int64{20}, dependencies: []uint64{2},
123			queuedAt: base.Add(3 * time.Second),
124			status:   StatusQueued,
125		})
126		// 作业 4：与重复记录无关的排队作业，重开后应照常完成。
127		writeSyntheticRecord(t, dir, &storedJob{
128			id: 4, submitter: "b", requestID: "indep",
129			values:   []int64{1, 2, 3},
130			queuedAt: base.Add(4 * time.Second),
131			status:   StatusQueued,
132		})
133	
134		s, err := Open(dir)
135		if err != nil {
136			t.Fatal(err)
137		}
138		defer s.Close()
139	
140		assertDuplicateDependencyFailure(t, s, 2, 1)
141	
142		// 被重复引用的上游仍保留自己的成功结果。
143		gUp, _ := s.Get(1)
144		if gUp.Status != StatusSucceeded || gUp.Archive == nil || gUp.Archive.Sum != 3 {
145			t.Fatalf("duplicated-but-valid upstream must keep its result: status=%s archive=%v",
146				gUp.Status, gUp.Archive)
147		}
148	
149		// 下游按既有依赖失败规则处理：直接上游是作业 2，根因也是作业 2
150		//（重复记录自身 BlockerID 为 0，根因不另指他人）。
151		child := waitStatus(t, s, 3, StatusFailed)
152		if child.BlockerID != 2 {
153			t.Fatalf("child blocker=%d want root 2 (the duplicate record itself)", child.BlockerID)
154		}
155		if !strings.Contains(child.FailureReason, "直接上游作业 2") ||
156			!strings.Contains(child.FailureReason, "依赖列表重复") {
157			t.Fatalf("child must name direct upstream 2 and carry its duplicate reason: %q",
158				child.FailureReason)
159		}
160		if child.Archive != nil || !child.StartedAt.IsZero() {
161			t.Fatalf("blocked child must never compute: started=%s archive=%v",
162				child.StartedAt, child.Archive)
163		}
164	
165		// 无关记录继续正常查询与调度。
166		indep := waitStatus(t, s, 4, StatusSucceeded)
167		if indep.Archive.Sum != 6 || indep.Archive.SumOfSquares != 14 {
168			t.Fatalf("unrelated job result=%d,%d want 6,14", indep.Archive.Sum, indep.Archive.SumOfSquares)
169		}
170	
171		// 再次重开：失败结果已保存在目录中，状态、原因与根因保持稳定，归档仍可用。
172		if err := s.Close(); err != nil {
173			t.Fatal(err)
174		}
175		s3, err := Open(dir)
176		if err != nil {
177			t.Fatal(err)
178		}
179		defer s3.Close()
180		assertDuplicateDependencyFailure(t, s3, 2, 1)
181		gChild2 := waitStatus(t, s3, 3, StatusFailed)
182		if gChild2.BlockerID != 2 {
183			t.Fatalf("after second reopen child blocker=%d want 2", gChild2.BlockerID)
184		}
185	}
186	
187	// 重复引用不要求相邻：[a,b,a] 中作业 a 隔着 b 再次出现，失败原因指出首次
188	// 再次出现的 a；被引用的两个上游都保持成功。
189	func TestReopenRejectsNonAdjacentDuplicateDependency(t *testing.T) {
190		dir := t.TempDir()
191		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
192		// 作业 1 总和 3，作业 2 总和 5。
193		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
194		syntheticSucceededRecord(t, dir, 2, []int64{5}, []int64{5}, nil, base)
195		// 作业 3：依赖 [1,2,1]，实际输入 [10,3,5,3]（sum=21, sq=143，全套自洽）。
196		dup := syntheticSucceededRecord(t, dir, 3,
197			[]int64{10}, []int64{10, 3, 5, 3}, []uint64{1, 2, 1}, base)
198		if dup.archive.Sum != 21 || dup.archive.SumOfSquares != 143 {
199			t.Fatalf("dup result=%d,%d want 21,143", dup.archive.Sum, dup.archive.SumOfSquares)
200		}
201	
202		s, err := Open(dir)
203		if err != nil {
204			t.Fatal(err)
205		}
206		defer s.Close()
207	
208		assertDuplicateDependencyFailure(t, s, 3, 1)
209		for _, id := range []uint64{1, 2} {
210			g, _ := s.Get(id)
211			if g.Status != StatusSucceeded || g.Archive == nil {
212				t.Fatalf("valid upstream %d must stay succeeded: %s", id, g.Status)
213			}
214		}
215	}
216	
217	// 排队记录的依赖列表重复时，重开后直接失败，不能开始计算（无开始时间、
218	// 无归档与实际输入）；等待它的下游随之失败，根因为该重复记录自身。
219	func TestReopenQueuedDuplicateDependencyFailsWithoutComputing(t *testing.T) {
220		dir := t.TempDir()
221		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
222		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
223		// 作业 2：排队，依赖列表重复 [1,1]。
224		writeSyntheticRecord(t, dir, &storedJob{
225			id: 2, submitter: "a", requestID: "dup",
226			values: []int64{10}, dependencies: []uint64{1, 1},
227			queuedAt: base.Add(2 * time.Second),
228			status:   StatusQueued,
229		})
230		// 作业 3：排队等待作业 2。
231		writeSyntheticRecord(t, dir, &storedJob{
232			id: 3, submitter: "a", requestID: "child",
233			values: []int64{20}, dependencies: []uint64{2},
234			queuedAt: base.Add(3 * time.Second),
235			status:   StatusQueued,
